import subprocess, pathlib
H = pathlib.Path.home()
roots = [H/"DEV", H/"DEV/Football", H/"DEV/SpecialRequests"]
repos = set()
for root in roots:
    for p in root.glob("*/.git"):
        repos.add(p.parent)
    if (root/".git").exists():
        repos.add(root)
repos |= {H/".claude", H/".claude/skills", H/".claude/global-memory"}
def run(r, *a):
    return subprocess.run(["git", "-C", str(r), *a], capture_output=True, text=True).stdout
for r in sorted(repos):
    dirty = [l for l in run(r, "status", "--porcelain").splitlines() if l.strip()]
    ahead = run(r, "rev-list", "--count", "@{u}..HEAD").strip() or "?"
    if dirty or ahead not in ("0",):
        print(f"{r} dirty={len(dirty)} ahead={ahead}")
        for l in dirty[:6]:
            print("   ", l)

